export default class YouTube {
  constructor(element) {
    this.element = element;

    this.videoContainer = this.element.querySelector('.js-video');
    this.poster = this.element.querySelector('.js-poster');
    this.dataControl = this.element.hasAttribute('data-no-controls');
    this.videoId = this.element.dataset.videoId;

    this.options = {
      //Autoplay est égal à poster si il est vrai(1) sinon is est faux (0)
      autoplay: this.poster ? 1 : 0,
      controls: !this.dataControl ? 1 : 0,
      playerReady: false,
    };

    YouTube.instances.push(this);
    //le push this correspond a l'instance de Video.js

    if (this.videoId) {
      YouTube.loadScript();
    } else {
      console.log('Vous devez spécifier un id');
    }
  }

  static loadScript() {
    if (!YouTube.scriptIsLoading) {
      YouTube.scriptIsLoading = true;

      //Crée le script puis l'API de youtube dans le frame, finalement l'insère dans le HTML
      const script = document.createElement('script');
      script.src = 'https://www.youtube.com/iframe_api';
      document.body.appendChild(script);
    }
  }

  init() {
    this.initPlayer = this.initPlayer.bind(this);

    if (this.poster) {
      this.element.addEventListener('click', this.initPlayer.bind(this));
    } else {
      this.initPlayer();
    }
  }

  initPlayer(event) {
    if (event) {
      this.element.removeEventListener('click', this.initPlayer);
    }

    this.player = new YT.Player(this.videoContainer, {
      height: '100%',
      width: '100%',
      videoId: this.videoId,
      playerVars: {
        rel: 0,
        autoplay: this.options.autoplay,
        controls: this.options.controls,
      },
      events: {
        //le OnReady permet de vérifier si la vidéo soit prête à jouer
        onReady: () => {
          //Permet de mettre la variable a true pour valider sa prêteter
          this.options.playerReady = true;
          //Créer l'observer pour le scrolling/observation de la page
          const observer = new IntersectionObserver(this.watch.bind(this), {
            rootMargin: '0px 0px 0px 0px',
          });
          observer.observe(this.element);
        },
        onStateChange: (event) => {
          if (event.data == YT.PlayerState.PLAYING) {
            //Permet de sélectionner la video actuel et son état (Joue ou joue pas)
            YouTube.pauseAll(this);
          } else if (event.data == YT.PlayerState.ENDED) {
            //Le else if vérifie si la fini est fini puis retourne le temps a 0 et pause la video
            this.player.seekTo(0);
            this.player.pauseVideo();
          }
        },
      },
    });
  }

  watch(entries) {
    //Permet de voir quand la vidéo sort de l'écran puis la pause
    if (this.options.playerReady && !entries[0].isIntersecting) {
      this.player.pauseVideo();
    }
  }

  static initAll() {
    //Initialise toute les vidéos et et leur met la classe is-video-ready
    document.documentElement.classList.add('is-video-ready');
    for (let i = 0; i < YouTube.instances.length; i++) {
      const instance = YouTube.instances[i];
      instance.init();
    }
  }

  static pauseAll(currentInstance) {
    for (let i = 0; i < YouTube.instances.length; i++) {
      const instance = YouTube.instances[i];
      //Le if vérifie si c'est l'instance qui est en train de jouer et vérifier si le player est sur l'instance
      if (instance.options.playerReady && instance !== currentInstance) {
        instance.player.pauseVideo();
      }
    }
  }
}

//Instace super global (hors de l'instance)
YouTube.instances = [];
window.onYouTubeIframeAPIReady = YouTube.initAll;
