import { gsap } from 'gsap';
import * as THREE from 'three';

export default class CircularGallery {
  constructor(element) {
    this.element = element;

    //Prend la police et la couleur des textes du site (lues dans le CSS)
    const firstText = this.element.querySelector('p') || this.element;
    const style = getComputedStyle(firstText);

    this.options = {
      bend: 3, //Courbure de l'arc (négatif = inversé, 0 = plat)
      borderRadius: 0.05, //Coins arrondis des images
      textColor: style.color,
      font: `500 14px ${style.fontFamily}`,
      scrollSpeed: 2, //Vitesse du glisser
      scrollEase: 0.05, //Douceur du mouvement (plus petit = plus fluide)
    };

    this.scroll = { current: 0, target: 0, last: 0, position: 0 };
    this.medias = [];
    this.isDown = false;
    this.isVisible = true;

    this.init();
  }

  /* ==========================================================================
      / Init
     ========================================================================== */

  init() {
    this.setOptions();
    this.getItems();
    this.createShaders();
    this.createRenderer();
    this.createCamera();
    this.onResize();
    this.initEvents();

    //Attend que la police du site soit chargée avant de dessiner les textes
    document.fonts.ready.then(() => {
      this.createMedias();

      //Une seule boucle GSAP pour l'animation (comme dans Raindrop)
      this.update = this.update.bind(this);
      gsap.ticker.add(this.update);
    });
  }

  /* ==========================================================================
      / Set Options (via les data-attributes du HTML)
     ========================================================================== */

  setOptions() {
    for (const key in this.options) {
      if (!(key in this.element.dataset)) continue;
      const value = this.element.dataset[key];

      if (typeof this.options[key] === 'number') {
        this.options[key] = parseFloat(value);
      } else {
        this.options[key] = value;
      }
    }
  }

  //Récupère les images et les textes directement dans le HTML
  getItems() {
    const articles = this.element.querySelectorAll('article');
    this.items = [];

    for (let i = 0; i < articles.length; i++) {
      const img = articles[i].querySelector('img');
      const text = articles[i].querySelector('p');

      this.items.push({
        image: img ? img.currentSrc || img.src : '',
        text: text ? text.textContent.trim() : '',
      });
    }
  }

  /* ==========================================================================
      / Shaders
     ========================================================================== */

  createShaders() {
    this.shaders = {
      //Image : ondule légèrement selon la vitesse du défilement
      imageVertex: `
        uniform float uTime;
        uniform float uSpeed;
        varying vec2 vUv;
        void main() {
          vUv = uv;
          vec3 p = position;
          p.z = (sin(p.x * 4.0 + uTime) * 1.5 + cos(p.y * 2.0 + uTime) * 1.5) * (0.1 + uSpeed * 0.5);
          gl_Position = projectionMatrix * modelViewMatrix * vec4(p, 1.0);
        }
      `,

      //Image : effet "object-fit: cover" + coins arrondis
      imageFragment: `
        uniform vec2 uImageSizes;
        uniform vec2 uPlaneSizes;
        uniform sampler2D tMap;
        uniform float uBorderRadius;
        varying vec2 vUv;

        float roundedBoxSDF(vec2 p, vec2 b, float r) {
          vec2 d = abs(p) - b;
          return length(max(d, vec2(0.0))) + min(max(d.x, d.y), 0.0) - r;
        }

        void main() {
          vec2 ratio = vec2(
            min((uPlaneSizes.x / uPlaneSizes.y) / (uImageSizes.x / uImageSizes.y), 1.0),
            min((uPlaneSizes.y / uPlaneSizes.x) / (uImageSizes.y / uImageSizes.x), 1.0)
          );
          vec2 uv = vec2(
            vUv.x * ratio.x + (1.0 - ratio.x) * 0.5,
            vUv.y * ratio.y + (1.0 - ratio.y) * 0.5
          );
          vec4 color = texture2D(tMap, uv);

          float d = roundedBoxSDF(vUv - 0.5, vec2(0.5 - uBorderRadius), uBorderRadius);
          float alpha = 1.0 - smoothstep(-0.002, 0.002, d);

          gl_FragColor = vec4(color.rgb, alpha);
        }
      `,

      //Texte sous chaque image
      textVertex: `
        varying vec2 vUv;
        void main() {
          vUv = uv;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,

      textFragment: `
        uniform sampler2D tMap;
        varying vec2 vUv;
        void main() {
          vec4 color = texture2D(tMap, vUv);
          if (color.a < 0.1) discard;
          gl_FragColor = color;
        }
      `,
    };
  }

  /* ==========================================================================
      / Renderer, caméra et scène
     ========================================================================== */

  createRenderer() {
    this.renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true });
    //Limite la densité de pixels à 2 pour garder de bonnes performances
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    this.renderer.setClearColor(0x000000, 0);

    this.canvas = this.renderer.domElement;
    this.canvas.classList.add('circular-gallery__canvas');
    this.canvas.setAttribute('aria-hidden', 'true');
    this.element.appendChild(this.canvas);

    this.scene = new THREE.Scene();
  }

  createCamera() {
    this.camera = new THREE.PerspectiveCamera(45, 1, 0.1, 100);
    this.camera.position.z = 20;
  }

  /* ==========================================================================
      / Création des cartes (image + texte)
     ========================================================================== */

  createMedias() {
    //Une seule géométrie partagée par toutes les cartes (plus léger)
    this.geometry = new THREE.PlaneGeometry(1, 1, 100, 50);
    this.textGeometry = new THREE.PlaneGeometry(1, 1);

    //Double la liste pour que la boucle infinie n'ait jamais de trou
    const list = this.items.concat(this.items);

    for (let i = 0; i < list.length; i++) {
      const media = this.createMedia(list[i], i, list.length);
      this.resizeMedia(media);
      this.medias.push(media);
    }
  }

  createMedia(item, index, length) {
    const media = {
      index: index,
      length: length,
      extra: 0,
    };

    //Le groupe porte la position et la rotation : l'image et le texte bougent ensemble
    media.group = new THREE.Group();
    this.scene.add(media.group);

    this.createImage(media, item.image);
    this.createTitle(media, item.text);

    return media;
  }

  createImage(media, image) {
    media.material = new THREE.ShaderMaterial({
      vertexShader: this.shaders.imageVertex,
      fragmentShader: this.shaders.imageFragment,
      transparent: true,
      depthTest: false,
      depthWrite: false,
      uniforms: {
        tMap: { value: null },
        uPlaneSizes: { value: new THREE.Vector2(1, 1) },
        uImageSizes: { value: new THREE.Vector2(1, 1) },
        uSpeed: { value: 0 },
        uTime: { value: 100 * Math.random() },
        uBorderRadius: { value: this.options.borderRadius },
      },
    });

    media.mesh = new THREE.Mesh(this.geometry, media.material);
    media.mesh.visible = false; //Caché tant que l'image n'est pas chargée
    media.group.add(media.mesh);

    new THREE.TextureLoader().load(image, (texture) => {
      media.material.uniforms.tMap.value = texture;
      media.material.uniforms.uImageSizes.value.set(
        texture.image.naturalWidth,
        texture.image.naturalHeight,
      );
      media.mesh.visible = true;
    });
  }

  createTitle(media, text) {
    const font = this.options.font;

    //Dessine le texte dans un canvas (x2 pour qu'il reste net)
    const pixelScale = 2;
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    ctx.font = font;

    const fontSize = parseInt((font.match(/(\d+)px/) || [0, 30])[1], 10);
    const textWidth = Math.ceil(ctx.measureText(text).width) + 20;
    const textHeight = Math.ceil(fontSize * 1.2) + 20;

    canvas.width = textWidth * pixelScale;
    canvas.height = textHeight * pixelScale;
    ctx.scale(pixelScale, pixelScale);
    ctx.font = font;
    ctx.fillStyle = this.options.textColor;
    ctx.textBaseline = 'middle';
    ctx.textAlign = 'center';
    ctx.fillText(text, textWidth / 2, textHeight / 2);

    media.textTexture = new THREE.CanvasTexture(canvas);
    media.textTexture.generateMipmaps = false;
    media.textTexture.minFilter = THREE.LinearFilter;
    media.textAspect = textWidth / textHeight;

    media.textMaterial = new THREE.ShaderMaterial({
      vertexShader: this.shaders.textVertex,
      fragmentShader: this.shaders.textFragment,
      transparent: true,
      depthTest: false,
      depthWrite: false,
      uniforms: { tMap: { value: media.textTexture } },
    });

    media.title = new THREE.Mesh(this.textGeometry, media.textMaterial);
    media.group.add(media.title);
  }

  /* ==========================================================================
      / Events
     ========================================================================== */

  initEvents() {
    this.onPointerDown = this.onPointerDown.bind(this);
    this.onPointerMove = this.onPointerMove.bind(this);
    this.onPointerUp = this.onPointerUp.bind(this);
    this.onWheel = this.onWheel.bind(this);
    this.onKeyDown = this.onKeyDown.bind(this);
    this.onCheck = this.onCheck.bind(this);

    //Glisser à la souris ou au doigt, seulement sur la galerie
    this.element.addEventListener('pointerdown', this.onPointerDown);
    this.element.addEventListener('pointermove', this.onPointerMove);
    this.element.addEventListener('pointerup', this.onPointerUp);
    this.element.addEventListener('pointercancel', this.onPointerUp);

    //Molette horizontale (trackpad) seulement : la molette verticale reste au ScrollSmoother
    this.element.addEventListener('wheel', this.onWheel, { passive: false });

    //Flèches du clavier quand la galerie a le focus
    this.element.addEventListener('keydown', this.onKeyDown);

    //Redimensionne quand la galerie change de taille
    this.resizeObserver = new ResizeObserver(this.onResize.bind(this));
    this.resizeObserver.observe(this.element);

    //Arrête le rendu quand la galerie n'est pas à l'écran
    this.intersectionObserver = new IntersectionObserver((entries) => {
      this.isVisible = entries[0].isIntersecting;
    });
    this.intersectionObserver.observe(this.element);
  }

  onPointerDown(e) {
    this.isDown = true;
    this.scroll.position = this.scroll.current;
    this.start = e.clientX;
    this.element.setPointerCapture(e.pointerId);
  }

  onPointerMove(e) {
    if (!this.isDown) return;
    const distance =
      (this.start - e.clientX) * (this.options.scrollSpeed * 0.025);
    this.scroll.target = this.scroll.position + distance;
  }

  onPointerUp() {
    if (!this.isDown) return;
    this.isDown = false;
    this.onCheck();
  }

  onWheel(e) {
    //Ignore la molette verticale pour ne pas bloquer le scroll de la page
    if (Math.abs(e.deltaX) <= Math.abs(e.deltaY)) return;
    e.preventDefault();
    this.scroll.target += e.deltaX * 0.005 * this.options.scrollSpeed;
    this.checkLater();
  }

  onKeyDown(e) {
    if (!this.medias.length) return;
    const step = this.medias[0].width;

    if (e.key === 'ArrowRight') {
      this.scroll.target += step;
    } else if (e.key === 'ArrowLeft') {
      this.scroll.target -= step;
    } else {
      return;
    }

    e.preventDefault();
    this.checkLater();
  }

  //Attend 0.2s sans mouvement avant d'aligner la carte (remplace le debounce)
  checkLater() {
    if (this.checkCall) this.checkCall.kill();
    this.checkCall = gsap.delayedCall(0.2, this.onCheck);
  }

  //Aligne la carte la plus proche au centre (snap)
  onCheck() {
    if (!this.medias.length) return;
    const width = this.medias[0].width;
    const itemIndex = Math.round(Math.abs(this.scroll.target) / width);
    const item = width * itemIndex;
    this.scroll.target = this.scroll.target < 0 ? -item : item;
  }

  /* ==========================================================================
      / Resize
     ========================================================================== */

  onResize() {
    this.screen = {
      width: this.element.clientWidth,
      height: this.element.clientHeight,
    };

    this.renderer.setSize(this.screen.width, this.screen.height, false);
    this.camera.aspect = this.screen.width / this.screen.height;
    this.camera.updateProjectionMatrix();

    //Taille visible de la scène (en unités 3D) à la distance de la caméra
    const fov = (this.camera.fov * Math.PI) / 180;
    const height = 2 * Math.tan(fov / 2) * this.camera.position.z;
    this.viewport = { width: height * this.camera.aspect, height: height };

    for (const media of this.medias) {
      this.resizeMedia(media);
    }
  }

  resizeMedia(media) {
    //Taille des cartes : 700 x 900 "pixels" de référence, adaptée à la hauteur de la galerie
    const scale = this.screen.height / 1500;
    const planeHeight =
      (this.viewport.height * (900 * scale)) / this.screen.height;
    const planeWidth =
      (this.viewport.width * (700 * scale)) / this.screen.width;

    media.mesh.scale.set(planeWidth, planeHeight, 1);
    media.material.uniforms.uPlaneSizes.value.set(planeWidth, planeHeight);

    //Le texte sous l'image
    const textHeight = planeHeight * 0.15;
    media.title.scale.set(textHeight * media.textAspect, textHeight, 1);
    media.title.position.y = -planeHeight * 0.5 - textHeight * 0.5 - 0.05;

    const padding = 2;
    media.width = planeWidth + padding;
    media.widthTotal = media.width * media.length;
    media.x = media.width * media.index;
  }

  /* ==========================================================================
      / Boucle d'animation
     ========================================================================== */

  update() {
    if (!this.isVisible) return;

    this.scroll.current = gsap.utils.interpolate(
      this.scroll.current,
      this.scroll.target,
      this.options.scrollEase,
    );
    const direction = this.scroll.current > this.scroll.last ? 'right' : 'left';

    for (const media of this.medias) {
      this.updateMedia(media, direction);
    }

    this.renderer.render(this.scene, this.camera);
    this.scroll.last = this.scroll.current;
  }

  updateMedia(media, direction) {
    const group = media.group;
    group.position.x = media.x - this.scroll.current - media.extra;

    //Courbe en arc : plus la carte est loin du centre, plus elle descend et tourne
    const x = group.position.x;
    const H = this.viewport.width / 2;
    const bend = this.options.bend;

    if (bend === 0) {
      group.position.y = 0;
      group.rotation.z = 0;
    } else {
      const B = Math.abs(bend);
      const R = (H * H + B * B) / (2 * B);
      const effectiveX = Math.min(Math.abs(x), H);
      const arc = R - Math.sqrt(R * R - effectiveX * effectiveX);

      if (bend > 0) {
        group.position.y = -arc;
        group.rotation.z = -Math.sign(x) * Math.asin(effectiveX / R);
      } else {
        group.position.y = arc;
        group.rotation.z = Math.sign(x) * Math.asin(effectiveX / R);
      }
    }

    //Vitesse du défilement => ondulation de l'image
    media.material.uniforms.uTime.value += 0.04;
    media.material.uniforms.uSpeed.value =
      this.scroll.current - this.scroll.last;

    //Boucle infinie : une carte sortie d'un côté repasse de l'autre
    const planeOffset = media.mesh.scale.x / 2;
    const viewportOffset = this.viewport.width / 2;
    const isBefore = group.position.x + planeOffset < -viewportOffset;
    const isAfter = group.position.x - planeOffset > viewportOffset;

    if (direction === 'right' && isBefore) media.extra -= media.widthTotal;
    if (direction === 'left' && isAfter) media.extra += media.widthTotal;
  }

  /* ==========================================================================
      / Destroy (si tu retires la galerie de la page)
     ========================================================================== */

  destroy() {
    gsap.ticker.remove(this.update);
    if (this.checkCall) this.checkCall.kill();
    this.resizeObserver.disconnect();
    this.intersectionObserver.disconnect();

    this.element.removeEventListener('pointerdown', this.onPointerDown);
    this.element.removeEventListener('pointermove', this.onPointerMove);
    this.element.removeEventListener('pointerup', this.onPointerUp);
    this.element.removeEventListener('pointercancel', this.onPointerUp);
    this.element.removeEventListener('wheel', this.onWheel);
    this.element.removeEventListener('keydown', this.onKeyDown);

    for (const media of this.medias) {
      media.material.dispose();
      media.textMaterial.dispose();
      media.textTexture.dispose();
      if (media.material.uniforms.tMap.value)
        media.material.uniforms.tMap.value.dispose();
    }

    if (this.geometry) this.geometry.dispose();
    if (this.textGeometry) this.textGeometry.dispose();
    this.renderer.dispose();
    this.canvas.remove();
  }
}
