import { gsap } from 'gsap';
import { ScrollSmoother } from 'gsap/ScrollSmoother.js';
import { ScrollTrigger } from 'gsap/ScrollTrigger.js';
import { log } from 'three';

export default class Lines {
  constructor(element) {
    //register des plugins mis dans le gsap
    gsap.registerPlugin(ScrollSmoother, ScrollTrigger);
    this.element = element;
    this.options = {
      offset: -250,
    };

    this.line = this.element.querySelector('.path-ligne');
    this.path = this.element.querySelector('path');
    this.pathLength = this.path.getTotalLength();
    this.panels = this.element.querySelectorAll('.js-panel');

    this.init();
  }

  init() {
    this.setOptions();

    if (this.line && this.panels.length) {
      this.initHoriz();
      return;
    }

    gsap.set(this.path, {
      strokeDasharray: this.pathLength,
      strokeDashoffset: this.pathLength,
    });

    gsap.to(this.path, {
      strokeDashoffset: this.options.offset,
      ease: 'none',
      scrollTrigger: {
        trigger: this.element,
        start: 'top center',
        end: 'bottom center',
        scrub: 0.5,
      },
    });

    // gsap.to(this.line, {
    //   clipPath: 'inset(0 0% 0 0)',
    //   strokeDashoffset: this.options.offset,
    //   ease: 'none',
    //   scrollTrigger: {
    //     trigger: this.element.querySelector('.container_competences'),
    //     endTrigger: this.panels[this.panels.length - 1],
    //     start: 'top 15px',
    //     end: 'bottom 25%',
    //     // scrub: 0.5,
    //     markers: true,
    //   },
    // });

    // console.log(this.panels[0]);
  }

  setOptions() {
    if ('offset' in this.element.dataset) {
      this.options.offset = this.element.dataset.offset;
      console.log(this.options.offset);
    }
  }

  initHoriz() {
    // ⚠️ Doivent être identiques à Scroll.js > initHoriz()
    const STAGGER = 0.2; // stagger des panels
    const DURATION = 0.5; // durée par défaut d'un tween GSAP

    const svg = this.line.closest('svg');

    // Position (en %) jusqu'où la ligne est dessinée quand chaque carte arrive :
    // la fin de chaque point du SVG (viewBox 1205 de large), la dernière carte termine la ligne.
    const dotEnds = [16, 429, 837];
    const stops = Array.from(this.panels, (panel, i) =>
      i === this.panels.length - 1 ? 100 : (dotEnds[i] / 1205) * 100,
    );

    // La ligne est un "fill" (pas un stroke) : on la révèle avec un clip-path
    gsap.set(svg, { clipPath: 'inset(0% 100% 0% 0%)' });

    // Même trigger / start / end / scrub que le pin horizontal de Scroll.js
    const tl = gsap.timeline({
      scrollTrigger: {
        trigger: this.element,
        start: 'top 100%',
        end: () => '+=' + this.element.offsetWidth,
        scrub: 1,
        invalidateOnRefresh: true,
      },
    });

    // Chaque segment se termine quand sa carte finit d'arriver
    let previousEnd = 0;
    this.panels.forEach((panel, i) => {
      const arrival = i * STAGGER + DURATION;
      tl.to(
        svg,
        {
          clipPath: `inset(0% ${100 - stops[i]}% 0% 0%)`,
          duration: arrival - previousEnd,
          ease: 'none',
        },
        previousEnd,
      );
      previousEnd = arrival;
    });
  }

  setOptions() {
    if ('offset' in this.element.dataset) {
      this.options.offset = this.element.dataset.offset;
    }
  }
}
